use super::*;

//----------------------------------------------------------------

/// Supplies suggested strings in a property's parsing format.
///
/// Properties store the provider directly. The default provider `()` takes no
/// space and returns `None`. Borrowed slices and arrays supply explicit choices.
/// [`EnumValues`] supplies the static names generated by [`enum_string!`]
/// without storing them in the property. [`EnumProp`] selects it automatically.
pub trait ValuesProvider {
	/// Returns suggested strings, or `None` when there are no fixed suggestions.
	fn values(&self) -> Option<&[&str]>;
}

impl ValuesProvider for () {
	fn values(&self) -> Option<&[&str]> {
		None
	}
}

impl ValuesProvider for &[&str] {
	fn values(&self) -> Option<&[&str]> {
		Some(*self)
	}
}

impl<const N: usize> ValuesProvider for &[&str; N] {
	fn values(&self) -> Option<&[&str]> {
		Some(*self)
	}
}

//----------------------------------------------------------------

/// Property values that can be displayed and downcast to their concrete type.
///
/// Implemented automatically for all `'static` types that implement [`fmt::Display`].
/// Reading a value does not require cloning, comparison, or parsing.
/// Property implementations determine which operations are supported on the value.
pub trait IValue: any::Any + fmt::Display {
	/// Returns the name of the concrete type.
	#[cfg(feature = "type_name")]
	fn type_name(&self) -> &str {
		any::type_name::<Self>()
	}
}
impl fmt::Debug for dyn IValue {
	fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
		fmt::Display::fmt(self, f)
	}
}

impl dyn IValue {
	/// Returns `true` if the inner type is the same as `T`.
	#[inline]
	pub fn is<T: any::Any>(&self) -> bool {
		(self as &dyn any::Any).is::<T>()
	}

	/// Returns some reference to the inner value if it is of type `T`, or `None` if it isn't.
	#[inline]
	pub fn downcast_ref<T: any::Any>(&self) -> Option<&T> {
		(self as &dyn any::Any).downcast_ref::<T>()
	}
}

impl<T: any::Any + fmt::Display> IValue for T {}

//----------------------------------------------------------------

/// Formats a property's value without changing its concrete type.
///
/// Implement this on a format type passed to a property's `with_format` method.
/// Read-only properties only require this trait; writable properties also require
/// [`ValueFromStr`]. Formatting can use temporary adapters without allocating.
pub trait ValueDisplay<T> {
	/// Formats the current value.
	fn fmt(&self, value: &T, f: &mut fmt::Formatter<'_>) -> fmt::Result;
}

/// Parses a property's value using a custom format.
///
/// Parsing produces the original value type. The property then applies its normal
/// assignment rules, including clamping where applicable.
pub trait ValueFromStr<T> {
	/// Error returned when the input cannot be parsed.
	type Err: fmt::Display;

	/// Parses text into a value before the property applies its assignment rules.
	fn parse(&self, input: &str) -> Result<T, Self::Err>;
}

/// Uses the value's ordinary [`fmt::Display`] and [`FromStr`] implementations.
#[derive(Copy, Clone, Debug, Default, Eq, PartialEq)]
pub struct DefaultFormat;

impl<T: fmt::Display> ValueDisplay<T> for DefaultFormat {
	fn fmt(&self, value: &T, f: &mut fmt::Formatter<'_>) -> fmt::Result {
		fmt::Display::fmt(value, f)
	}
}

impl<T: FromStr> ValueFromStr<T> for DefaultFormat
	where T::Err: fmt::Display
{
	type Err = T::Err;

	fn parse(&self, input: &str) -> Result<T, Self::Err> {
		input.parse()
	}
}
